window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-cirurgia-med-cir-08"]={"block":"med:med-cirurgia-med-cir-08","label":"MED · MED CIR 08","count":60,"questions":[{"id":"med-cirurgia-med-cir-08-315172","number":"315172","sourceNumber":"315172","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Segundo o disque 100, foram mais de 3milhoes de telefonemas com denúncias de\nmaus-tratos (MT) a crianças e adolescentes. Relacione a alternativa CORRETA:","options":{"A":"A família é sempre um porto seguro sem questionamentos em casos de violência.","B":"Fraturas de costelas em lactentes é muito raro e sempre associada a trauma de grande\nintensidade, deve-se sempre pensar em possível MT se a cinética não é compatível.","C":"A notificação dos suspeitos de maus tratos no atendimento hospitalar não é obrigatória.","D":"Raramente a criança que sofreu violência apresenta alguma mudança de comportamento.","E":"A violência sexual contra a criança acontece mais frequentemente por estranhos."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-315180","number":"315180","sourceNumber":"315180","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Qual das seguintes afirmações sobre trauma pediátrico no Brasil é verdadeira?","options":{"A":"Traumas relacionados aos veículos a motor somam menos de 10% de todas as lesões\npediátricas que resultam em óbito.","B":"Acidentes de trânsito é a principal causa de óbito em crianças e adolescentes de 1 a 14 anos.","C":"Capacetes de proteção para bicicleta não reduzem a gravidade da maioria dos traumatismos\ncrânio-encefálicos relacionados a bicicleta.","D":"A maioria dos óbitos relacionados ao fogo ocorrem nas escolas.","E":"O uso de equipamentos de contenção não reduziram os óbitos na faixa etária menor de 7 anos."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-212206","number":"212206","sourceNumber":"212206","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Paciente do sexo feminino vítima de trauma por arma de fogo teve lesão transfixante do\nhemitórax esquerdo, 5º espaço intercostal (entrada e saída), estando hemodinamicamente estável\ne sem dor abdominal. Qual a conduta mais adequada?","options":{"A":"Hemograma seriado.","B":"Toracotomia esquerda.","C":"Laparotomia exploradora.","D":"Observação clínica rigorosa.","E":"Exploração dos ferimentos para determinar conduta sequencial."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-219907","number":"219907","sourceNumber":"219907","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Em uma consulta de rotina, a mãe de um paciente de 1 ano e seis meses de idade,\npeso 10 kg (Z-score 0,23), estatura 84 cm\n(Z-score 0,10), relata que seu filho gosta de mexer em\ntudo. Ela demonstra-se bastante preocupada pois tem receio que seu filho se machuque, agora que\nconsegue andar sozinho pela casa. A respeito da prevenção de acidentes, a mãe deveria receber a\nseguinte orientação:","options":{"A":"Manter materiais pontiagudos ou cortantes e produtos tóxicos em local bem arejado na cozinha\nou área de serviço.","B":"Proteger cantos dos móveis, além de colocar barreiras de proteção nas escadas e janelas.","C":"Segurar a criança fortemente pela mão ao sair de casa, evitando que ele se solte e corra para a\nrua.","D":"Transportar a criança em assento de elevação (boosters) com cinto de três pontos no banco de\ntrás do carro."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-219908","number":"219908","sourceNumber":"219908","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Mãe de 3 filhos cujas idades são 1 ano, 5 anos e 12 anos, sendo que as crianças têm\nestaturas adequadas à idade. Ela fará uma viagem de carro com as crianças e está preocupada\ncom os cuidados de segurança que devem ser adotados. A alternativa CORRETA sobre a\nprevenção de acidentes automobilísticos na infância é:","options":{"A":"A criança de 1 ano deverá ser levada no bebê-conforto ou assento conversível, no banco de\ntrás, com face voltada para frente.","B":"A criança de 5 anos deve ser levada no banco de trás, com cinto de 3 pontos, com a face\nvoltada para frente.","C":"A criança de 12 anos pode ir no banco da frente utilizando o cinto de segurança de 3 pontos.","D":"Os assentos infantis podem ser fixado ao carro com a utilização de cinto de 2 pontos."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-212172","number":"212172","sourceNumber":"212172","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"O transporte seguro de crianças em automóveis deve ser baseado nas melhores\nevidencias cientificas e o pediatra tem a\nresponsabilidade de orientar sobre os equipamentos\ndisponíveis, seguros e adequados para cada fase de seu desenvolvimento. Nesse contexto, dadas\nas afirmativas, I. Os assentos de segurança específicos para o transporte de crianças em\nautomóveis têm as características adequadas às diversas fases do crescimento, desde a alta da\nmaternidade até o momento em que o adolescente atinge 1,45 m de altura, quando pode utilizar o\ncinto de segurança. II. Desde 2010, vigora no Brasil a Resolução no 277 do Conselho Nacional de\nTrânsito, segundo a qual menores de 10 anos devem ser transportados nos bancos traseiros,\nusando individualmente dispositivo de retenção apropriado para sua idade. III. O critério de peso\ncontinua sendo o mais fiel para a escolha do melhor assento, segundo evidências científicas atuais.\nverifica-se que está(ão) correta(s)","options":{"A":"I, apenas.","B":"III, apenas.","C":"I e II, apenas.","D":"II e III, apenas.","E":"I, II e III."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-187818","number":"187818","sourceNumber":"187818","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"LDU. 30 anos, foi vítima de atropelamento por automóvel em via de alta velocidade há\ninstantes. Deu entrada no pronto atendimento levado por populares e, ao exame apresentou: a-\nVias aéreas pérveas, dor à palpação da coluna cervical; b- MV abolido à direita, FR 36irpm, SatO?\n80%, desvio de traquéia para a esquerda; c- FC 130bpm, PA 70/50mmhg, hipocorado +/4+,\nsangramento ativo em miE; d- Glasgow 15, isocórico, sem déficits motores ou sensitivos grosseiros;\ne- Abdome levemente doloroso à palpação em hipocôndrio direito, pelve estável, deformidade com\nexposição de espícula óssea em perna esquerda (local de sangramento). Assinale a alternativa que\nmostra a conduta e a sequênica de atendimento CORRETOS a serem seguidas pelo médico\nassistente.","options":{"A":"Fornecer O2 suplementar por máscara com reservatório, posicionar colar cervical, radiografia de\ntórax em AP na sala de emergência, US (FAST) + compressão do sangramento ativo, alinhamento\ndo membro, reposição volêmica com cristaloide aquecido","B":"Fornecer O2 suplementar por máscara com reservatório, posicionar colar cervical, comprimir o\nsangramento em miE, reposição volêmica com cristaloides, solicitar vaga imediatamente no centro\ncirúrgico para drenagem torácica à direita, controle cirúrgico do sangramento em miE e correção da\nfratura exposta","C":"Fornecer O2 suplementar por máscara com reservatório, posicionar colar cervical,\ntoracocentese para descompressão no hemitórax\ndireito, drenagem torácica à direita, US (FAST) +\ncompressão do sangramento ativo, reposição volêmica com cristaloide aquecido, alinhamento do\nmembro deformado","D":"Fornecer O2 suplementar por máscara com reservatório, radiografia de tórax em AP na sala de\nemergência, compressão do sangramento ativo, alinhamento do miE, reposição volêmica com\ncristaloide aquecido a 39°C, posicionar colar cervical semirrigido"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-180127","number":"180127","sourceNumber":"180127","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Homem, 35 anos, caiu de andaime e é levado à emergência. Ao chega, o medico\nconstata haver crepitação em hemitórax esquerdo.\nExame físico: hipocorado e cianótico; ausculta\npulmonar abolida à esquerda; sem turgência jugular; PA = 90 x 60 mmHg. A principal hipótese\ndiagnostica é:","options":{"A":"Hemotórax maciço","B":"Tamponamento cardiaco","C":"Pneumotórax hipertensivo","D":"Contusão pulmonary","E":"Pneumotórax simples"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-180156","number":"180156","sourceNumber":"180156","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Segundo o disque 100, foram mais de 3milhoes de telefonemas com denúncias de\nmaus-tratos (MT) a crianças e adolescentes. Relacione a alternativa correta:","options":{"A":"A família é sempre um porto seguro sem questionamentos em casos de violência","B":"Fraturas de costelas em lactentes é muito raro e sempre associada a trauma de grande\nintensidade, deve-se sempre pensar em possível MT se a cinética não é compatível","C":"A notificação dos suspeitos de maus tratos no atendimento hospitalar não é obrigatória","D":"Raramente a criança que sofreu violência apresenta alguma mudança de comportamento","E":"A violência sexual contra a criança acontece mais frequentemente por estranhos"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-181427","number":"181427","sourceNumber":"181427","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Patrícia, há cerca de seis meses, leva seu filho de 11 anos para investigação\ndiagnóstica de crise convulsiva focal em\nmembros, sem fatores desencadeantes ou relação com\nsono, os quais surgem e cedem espontaneamente, já tendo sido realizada triagem com\nneuropediatria e eletroencefalograma, sem determinação de alterações em exame físico ou em\nexames complementares. É filho único de casal divorciado, há sete meses, saudável previamente,\ne com bom desenvolvimento neuropsicomotor. Qual a hipótese diagnóstica mais provável?","options":{"A":"Síndrome de Munchhausen por procuração.","B":"Encefalopatia mioclônica precoce.","C":"Síndrome de Panayiotopoulos.","D":"Epilepsia mioclônica juvenil.","E":"Síndrome de West."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-161363","number":"161363","sourceNumber":"161363","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"JAF, 43 anos, vítima de queda de moto, trazido ao pronto-socorro em prancha longa e\ncolar cervical, com trauma de face importante, submetido à cricotireoidostomia, ausculta pulmonar\nnormal, apresenta PA = 80 x 40 mmHg, frequência de pulso = 143 bpm, pressão de pulso\ndiminuída. Apresenta marca do cinto de segurança de três pontas em tórax e abdome. Frente a\nessa situação, aponte a opção que contém a perda sanguínea estimada, a classificação do choque\ne a conduta inicial mais adequada, RESPECTIVAMENTE.","options":{"A":"750 ? 1.500 mL / Choque grau II / Expansão volêmica com cristaloides.","B":"1.500 ? 2.000 mL / Choque grau III / Expansão volêmica com cristaloides e sangue.","C":"> 2.000 mL / Choque grau IV / Expansão volêmica com cristaloides e sangue.","D":"> 3.000 mL / Choque grau IV / Expansão volêmica com cristaloides e sangue."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-158440","number":"158440","sourceNumber":"158440","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"A síndrome do bebê sacudido compreende:","options":{"A":"Situação em que foi utilizada a força física de forma acidental praticada por outra criança\ndurante\numa brincadeira.","B":"Situação em que foi utilizada a força física de forma intencional, não acidental, praticada\nprovavelmente por um responsável pela criança.","C":"Negligência, um ato extremo de omissão, e deve-se ter cuidado ao imputar intenção ao evento.","D":"Maus tratos psicológicos, que podem causar danos ao desenvolvimento físico e psíquico da\ncriança.","E":"Criança espancada, pois são observados ferimentos inusitados que devem ser comprovados por\nradiografias."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-158394","number":"158394","sourceNumber":"158394","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Assinale a alternativa CORRETA. O acidente responsável pelo maior número de casos\nde mortalidade em crianças menores de cinco anos\né:","options":{"A":"A intoxicação aguda.","B":"O afogamento.","C":"A queimadura.","D":"O automobilístico.","E":"A queda."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-298226","number":"298226","sourceNumber":"298226","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Paciente do sexo masculino, 44 anos, é retirado pelos bombeiros do segundo andar de\numa casa em chamas. O paciente de\naproximadamente 70kg, apresentava queimaduras de\nsegundo grau em face (com queimadura de sobrancelhas, víbices nasais e secreção carbonácea\nem orofaringe), tórax anterior, abdome anterior e membro superior esquerdo. O paciente se\napresentava taquicárdico (110bpm), normotenso e taquipneico (30irpm), saturando 90% sob\nmáscara. Ele não responde a comandos verbais e responde a estímulos dolorosos com gemidos.\nSobre o caso descrito acima, assinale a alternativa INCORRETA:","options":{"A":"Há clara indicação de antibioticoprofilaxia pelo elevado risco de infecção das áreas queimadas e\npossível evolução para sepse.","B":"O primeiro passo no atendimento deste paciente é o acesso a via aérea definitiva,\npreferencialmente por intubação orotraqueal.","C":"Há indicação da dosagem de carboxihemoglobina devido ao elevado risco de intoxicação por\nmonóxido de carbono e de ventilação com O? a 100%.","D":"Segundo a American Burn Association, a reposição volêmica deste paciente deve ser realizada\ncom Ringer Lactato, num volume de\naproximadamente 275ml/h nas primeiras 8 horas e 138ml/h\nnas 16 horas seguintes."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-286723","number":"286723","sourceNumber":"286723","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Paciente do sexo masculino, 32 anos, vítima de ferimento abdominal penetrante em\nbriga de bar, localizado em transição do\nepigástrio e Hipocôndrio Direito, é admitido no pronto\nsocorro apresentando evidente palidez cutâneo mucosa. O paciente encontra-se ansioso e\nconfuso, FC: 120bpm, FR: 30irpm e P.A.: 90x60mmHg. Foi realizada sondagem vesical, com saída\nde 10ml de urina. Não havia trauma craniano, torácico ou de membros. Sobre a abordagem inicial\ndeste paciente, assinale a alternativa INCORRETA:","options":{"A":"Há indicação do uso de ácido tranexâmico e acompanhamento da função de coagulação através\ndo tromboelastograma.","B":"A cada 1.500ml de reposição com ringer lactato, está indicada a reposição de 1 concentrado de\nhemácias e a reposição de plaquetas e plasma fresco dependerão dos resultados do TAP, TTPA e\nhemograma.","C":"A medida inicial para ressuscitação volêmica deste paciente é a punção venosa única com\nJelco® 18, reposição de até 1 litro de cristaloide e reavaliação a resposta clínica à hidratação.","D":"A penetração na cavidade abdominal associada a instabilidade hemodinâmica do paciente\nprioriza a abordagem cirúrgica via laparotomia exploradora ao invés da laparoscopia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-176039","number":"176039","sourceNumber":"176039","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Júlia tem um ano e meio de idade e pesa 14 kg. Você fará recomendações para\nprevenção de injúrias não intencionais em\nacidentes de transporte, sendo a criança ocupante de\num automóvel. Assinale a assertiva CORRETA, baseado em orientações da Sociedade Brasileira\nde Pediatria (SBP):","options":{"A":"Utilizar assento infantil, tipo bebê-conforto,\ninstalado de frente para o painel do veículo.","B":"Utilizar assento infantil, tipo cadeirinha,\ninstalado de costas para o painel do veículo.","C":"Utilizar assento infantil, tipo bebê-conforto, instalado de costas para o painel do veículo.","D":"Utilizar assento infantil tipo cadeirinha, instalado de frente para o painel do veículo."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-284577","number":"284577","sourceNumber":"284577","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Paciente, sexo masculino, 20 anos de idade, é trazido pelo SAMU, vítima de trauma\nmoto x anteparo em via expressa há 30\nminutos. Dá entrada no Pronto Socorro com colar cervical e\nprancha rígida, referindo dor em hemitórax direito e falta de ar. Ao exame, A: Via aérea pérvia,\nmantido colar cervical, SatO2: 84% com cateter de O2 15L/min; B: murmúrios vesiculares\ndiminuídos com crépitos em hemitórax direito, FR: 36ipm; C: Bulhas rítmicas e normofonéticas, FC:\n98bpm, PA: 122x76mmHg, abdome indolor á palpação, pelve estável e toque retal sem alterações;\nD: escala de coma de Glasgow= 13, pupilas isocóricas e fotorreagentes; E: escoriações e dor à\npalpação em hemitórax direito. Foi realizado radiografia de tórax na sala de emergência. De acordo\ncom o caso e com o exame de imagem, indique a principal suspeita diagnóstica que justifique o\nquadro clínico descrito.","options":{"A":"Hemotórax.","B":"Pneumotórax.","C":"Tamponamento cardíaco.","D":"Tórax instável."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-284580","number":"284580","sourceNumber":"284580","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Paciente, sexo masculino, 27 anos de idade, é trazido por populares à Unidade de\nPronto Atendimento, UPA, após ser vítima de\nagressão física. Relata que sofreu agressão com um\nsoco na boca, há cerca de 45 minutos, após discussão em um bar. Refere ferimento em lábio\ninferior com dor e sangramento. Nega outros sintomas. Ao exame físico, bom estado geral, lúcido e\norientado, presença de ferimento corto-contuso em região central do lábio inferior, medindo 3cm de\nespessura total (exposição de mucosa), sem perda de substância e com sangramento ativo em\npequena quantidade. Indique a estrutura anatômica mais importante que deve ser reparada para\nque o paciente não evolua com sequela funcional na região oral.","options":{"A":"Músculo bucinador.","B":"Mucosa oral.","C":"Pele do lábio inferior.","D":"Músculo orbicular da boca."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-284581","number":"284581","sourceNumber":"284581","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Paciente, sexo masculino, 27 anos de idade, é trazido por populares à Unidade de\nPronto Atendimento, UPA, após ser vítima de\nagressão física. Relata que sofreu agressão com um\nsoco na boca, há cerca de 45 minutos, após discussão em um bar. Refere ferimento em lábio\ninferior com dor e sangramento. Nega outros sintomas. Ao exame físico, bom estado geral, lúcido e\norientado, presença de ferimento corto-contuso em região central do lábio inferior, medindo 3cm de\nespessura total (exposição de mucosa), sem perda de substância e com sangramento ativo em\npequena quantidade. Identifique o número mínimo de planos anatômicos que devem ser fechados\nno reparo do ferimento desse paciente.","options":{"A":"1","B":"2","C":"3","D":"4"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-259701","number":"259701","sourceNumber":"259701","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Uma mulher de 34 anos, que usava cinto de segurança, é envolvida em uma colisão\nautomobilística e foi atendida por uma equipe de suporte avançado do SAMU 192, sendo levada\npara sala de emergência do Hospital de Trauma. Segundo informações da equipe de pré-hospitalar\no Glasgow da paciente é 15 e sem evidências de lesão craniana. Durante o atendimento inicial na\nsala de emergência nota-se uma equimose em faixa na região cervical (foto) e na avaliação\nneurológica percebe-se que ela encontra-se sonolenta, abre os olhos ao comando verbal, conversa\nquando estimulada, mas repete algumas vezes perguntas já respondidas, obedece comandos para\nmovimento motor. Pupilas estão fotorreagentes e isocóricas. Não tem achado de lesões envolvendo\nface e couro cabeludo. Com base neste caso, qual o Glasgow da doente e a suspeita diagnóstica?","options":{"A":"Glasgow de 13 e hematoma epidural.","B":"Glasgow de 12 e suspeita de lesão axonal difusa.","C":"Glasgow de 12 e contusão ou concussão cerebral.","D":"Glasgow de 13 e acidente vascular cerebral isquêmico."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-259676","number":"259676","sourceNumber":"259676","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Um jovem de 21 anos se envolve em uma colisão moto x caminhão e apresenta\nmúltiplas lesões, sendo que uma delas é uma\nlesão complexa do membro inferior direito abaixo do\njoelho. Um sangramento ativo é observado nesse membro e populares realizam um torniquete\nimprovisado. Quando o médico do SAMU 192 chega na cena, com sua equipe, ele nota\nrapidamente o paciente sonolento e uma semi-amputação do membro com uma poça de sangue no\nchão. Considerando as informações iniciais deste caso e as recomendações atuais da abordagem\ndo doente de trauma no cenário pré-hospitalar, qual a primeira conduta de avaliação do paciente\nque deve ser priorizada?","options":{"A":"Verificar vias aéreas e aplicar o colar cervical.","B":"Estimar o grau de choque hemorrágico do doente.","C":"Avaliar a efetividade do torniquete aplicado pelos populares.","D":"Ofertar oxigênio suplementar e garantir uma via aérea definitiva."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-234022","number":"234022","sourceNumber":"234022","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Paciente de 25 anos foi admitida em emerge?ncia ciru?rgica vi?tima de trauma\nautomobili?stico e colisa?o frontal com outro\nvei?culo. Apo?s o atendimento inicial, houve\nestabilizac?a?o hemodina?mica seguinte a? expansa?o vole?mica e drenagem de\nhemopneumoto?rax a? esquerda. Estava consciente, orientada e com queixas a?lgicas no corpo\ntodo e em especial no membro inferior esquerdo, presenc?a de equimoses em pescoc?o, a?\nesquerda, to?rax e abdo?men em corresponde?ncia a a?rea de contato com o cinto de\nseguranc?a, enfisema subcuta?neo em hemito?rax esquerdo e fratura de corpo de fe?mur a?\nesquerda. A investigac?a?o por imagem evidenciou: ? Rx de to?rax: dreno bem posicionado, boa\nexpansa?o pulmonar, enfisema subcuta?neo. ? Rx de coluna cervical, Rx de pelve e\nultrassonografia de abdo?men sem anormalidades. ? Rx da coxa com fratura de dia?fise de fe?mur\nesquerdo. ? Tomografia computadorizada de cra?nio ? sem anormalidades. Foi internada e\nevolui?a bem, ate? que apo?s 48 horas de internac?a?o, evoluiu com hemiparesia a? esquerda.\n\nFeita nova TC de cra?nio, que evidenciou lesa?o fronto-temporo-parietal esquerda compati?vel com\nAVC isque?mico. Qual a prova?vel causa?","options":{"A":"Embolia gordurosa.","B":"Traumatismo cra?nio-encefa?lico.","C":"Lesa?o de arte?ria caro?tida interna.","D":"Tromboembolismo venoso profundo."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-199661","number":"199661","sourceNumber":"199661","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Mãe leva seu filho de 18 meses de idade para atendimento em urgência pediátrica com\nquadro de choro persistente após queda quando brincava no parquinho. Mãe relata que criança\ntem dificuldade de andar e sempre está caindo. Ao exame, a criança era eutrófica, apresentava-se\nassustada, bastante chorosa, com ausculta cardíaca e pulmonar normais, com dor à manipulação\nde membro inferior direito e presença de duas equimoses face medial e posterior da coxa direita. A\nradiografia de membros inferiores evidenciou fratura em metafisária em \"alça de balde\" em região\nde fêmur direito e presença de fratura em tíbia esquerda em consolidação. Diante do quadro acima\ndescrito, qual a melhor conduta?","options":{"A":"Providenciar a imobilização imediata do membro fraturado e encaminhamento para geneticista\npara avaliação e acompanhamento.","B":"Solicitar avaliação do ortopedista para imobilização do membro e posteriormente alta do\npaciente com orientações para cuidados no domicílio.","C":"Acionar o instituto médico legal para avaliação das lesões e providenciar encaminhamento para\ncentro de referência em traumatologia ortopédica infantil.","D":"Solicitar investigação radiológica completa e notificar a suspeita de maus tratos ao Conselho\nTutelar e no Sistema de Informação de Agravos de Notificação."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-150799","number":"150799","sourceNumber":"150799","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Um homem de 53 anos pilotava uma motocicleta quando sofreu uma colisão frontal\ncom um veículo que trafegava em sentido contrário. O SAMU foi acionado e o encontrou\ngravemente traumatizado. Nesse caso, qual o papel do serviço de atendimento pré-hospitalar?","options":{"A":"Realizar imediata triagem e decisão de remover o paciente.","B":"Inicialmente, avaliar o cenário para garantir a estabilização do paciente.","C":"Remover para o hospital mais próximo caso necessite de cuidados definitivos.","D":"Permanecer no cenário o tempo necessário para melhoria do quadro clínico do paciente."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-298840","number":"298840","sourceNumber":"298840","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Um paciente foi levado pelo Serviço de Atendimento Móvel de Urgência (SAMU) à\nemergência de um hospital com história de atropelamento há alguns minutos. Ao exame físico, o\npaciente apresenta FC = 110 bpm, FR = 28 irpm, SatO2 = 90% e PA = 100 mmHg x 75 mmHg. Ao\nser questionado, apenas verbaliza algumas palavras sem sentido, e demonstra abertura ocular à\ndor e resposta motora de flexão anormal. A ausculta respiratória indica murmúrio vesicular ausente\nà direita e normais à esquerda. Exames cardiovascular e abdominal não há alterações. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Na técnica de\ndrenagem pleural, deve-se transpassar o tubo de toracostomia no 5º espaço intercostal, levemente\nanterior à linha axilar anterior, posicionando o tubo superior e posteriormente ao tórax. O local de\ninserção do dreno de tórax é o mesmo em adultos e em crianças.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-298883","number":"298883","sourceNumber":"298883","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Uma paciente de 1 ano e 6 meses de idade foi encaminhada ao pronto atendimento\npediátrico por apresentar febre, há três\ndias, entre 38ºC e 39,5ºC, sem outras queixas. A criança foi\nlevada pela avó materna, que se mostrou bastante preocupada, pois, além da febre, notou que a\ncriança apresenta manchas arrocheadas nos membros superiores e inferiores. A criança reside\ncom a mãe, um irmão de 5 anos de idade e o padrasto. Ao exame físico, ela mostra-se abatida e\nprostrada, mas está corada e hidratada. Constataram-se FC = 120 bpm, FR = 40 irpm, SatO2 =\n98% em AA, oroscopia sem petéquias, sem placas, sem lesões, otoscopia com membrana\ntimpânica translúcida, sem abaulamento, sem secreção, ausculta cardíaca BNF, RR, 2t, sem sopro\ne ausculta pulmonar MVUD, sem ruídos adventícios. Também foram observados abdome RHA+,\ndepressível, dor à palpação em baixo ventre, Blumberg e Murph negativos, sem sinais de\nmeningismo, membros inferiores com equimoses < 5 cm e membros superiores com equimoses > 5\ncm em braço esquerdo. Inicialmente foram solicitados exame qualitativo de urina com urocultura\n(via sondagem vesical; ainda sem resultado da urocultura) e radiografia de membro superior\nesquerdo. O exame qualitativo de urina pode ser verificado a seguir. Realizou-se, ainda, radiografia\nque evidenciou calo ósseo em rádio e ulna esquerda, conforme a imagem a seguir. Acerca desse\ncaso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. Sempre\nque se observam equimoses em menores de 5 anos de idade, deve-se realizar uma investigação\nde hemofilia, por ser uma patologia bastante frequente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":["question_bank/media/medcurso/med-cirurgia-med-cir-08/298883.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-298886","number":"298886","sourceNumber":"298886","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Uma paciente de 1 ano e 6 meses de idade foi encaminhada ao pronto atendimento\npediátrico por apresentar febre, há três\ndias, entre 38ºC e 39,5ºC, sem outras queixas. A criança foi\nlevada pela avó materna, que se mostrou bastante preocupada, pois, além da febre, notou que a\ncriança apresenta manchas arrocheadas nos membros superiores e inferiores. A criança reside\ncom a mãe, um irmão de 5 anos de idade e o padrasto. Ao exame físico, ela mostra-se abatida e\nprostrada, mas está corada e hidratada. Constataram-se FC = 120 bpm, FR = 40 irpm, SatO2 =\n98% em AA, oroscopia sem petéquias, sem placas, sem lesões, otoscopia com membrana\ntimpânica translúcida, sem abaulamento, sem secreção, ausculta cardíaca BNF, RR, 2t, sem sopro\ne ausculta pulmonar MVUD, sem ruídos adventícios. Também foram observados abdome RHA+,\ndepressível, dor à palpação em baixo ventre, Blumberg e Murph negativos, sem sinais de\nmeningismo, membros inferiores com equimoses < 5 cm e membros superiores com equimoses > 5\ncm em braço esquerdo. Inicialmente foram solicitados exame qualitativo de urina com urocultura\n(via sondagem vesical; ainda sem resultado da urocultura) e radiografia de membro superior\nesquerdo. O exame qualitativo de urina pode ser verificado a seguir. Realizou-se, ainda, radiografia\nque evidenciou calo ósseo em rádio e ulna esquerda, conforme a imagem a seguir. Acerca desse\ncaso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. O\ntrauma contuso, nas crianças mais novas, muitas vezes é consequência dos maus-tratos e do\nespancamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":["question_bank/media/medcurso/med-cirurgia-med-cir-08/298886.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-298887","number":"298887","sourceNumber":"298887","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Uma paciente de 1 ano e 6 meses de idade foi encaminhada ao pronto atendimento\npediátrico por apresentar febre, há três\ndias, entre 38ºC e 39,5ºC, sem outras queixas. A criança foi\nlevada pela avó materna, que se mostrou bastante preocupada, pois, além da febre, notou que a\ncriança apresenta manchas arrocheadas nos membros superiores e inferiores. A criança reside\ncom a mãe, um irmão de 5 anos de idade e o padrasto. Ao exame físico, ela mostra-se abatida e\nprostrada, mas está corada e hidratada. Constataram-se FC = 120 bpm, FR = 40 irpm, SatO2 =\n98% em AA, oroscopia sem petéquias, sem placas, sem lesões, otoscopia com membrana\ntimpânica translúcida, sem abaulamento, sem secreção, ausculta cardíaca BNF, RR, 2t, sem sopro\ne ausculta pulmonar MVUD, sem ruídos adventícios. Também foram observados abdome RHA+,\ndepressível, dor à palpação em baixo ventre, Blumberg e Murph negativos, sem sinais de\nmeningismo, membros inferiores com equimoses < 5 cm e membros superiores com equimoses > 5\ncm em braço esquerdo. Inicialmente foram solicitados exame qualitativo de urina com urocultura\n(via sondagem vesical; ainda sem resultado da urocultura) e radiografia de membro superior\nesquerdo. O exame qualitativo de urina pode ser verificado a seguir. Realizou-se, ainda, radiografia\nque evidenciou calo ósseo em rádio e ulna esquerda, conforme a imagem a seguir. Acerca desse\ncaso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. Quando\nse observam fraturas múltiplas, bilaterais e em diferentes estágios de consolidação, deve-se pensar\nem maus-tratos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":["question_bank/media/medcurso/med-cirurgia-med-cir-08/298887.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-305319","number":"305319","sourceNumber":"305319","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Uma adolescente procura a emergência com queixa de dores abdominais intensas. Ao\nser avaliada pelo pediatra de plantão, ela\nrelata que está ali por estar precisando de ajuda. Conta\nque tem sofrido, em casa, diversas formas de violência. Cita, entre elas: beliscões, tapas,\nxingamentos, constrangimentos perante as visitas e que, algumas vezes, já ficou de castigo sem\nalimentos ou água. É muito importante, para saber como acolher os pacientes nessas situações e\npara identificar os pacientes em risco, que o pediatra conheça as formas de violência. Quanto ao\ntema, informe se é verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa com\na sequência correta. ( ) Violência física é entendida como a ação infligida à criança ou ao\nadolescente que ofenda sua integridade ou saúde corporal ou que lhe cause sofrimento físico. ( ) A\nalienação parental é um tipo de violência psicológica. ( ) Conduta que constranja a criança ou o\nadolescente a presenciar conjunção carnal é considerada violência sexual. ( ) Violência\ninstitucional\né entendida como a praticada por instituição pública ou conveniada, inclusive quando gerar\nrevitimização. ( ) Expor a criança ou o adolescente a isolamento ou indiferença é uma forma de\nviolência psicológica.","options":{"A":"V - V - V - V - V","B":"V - F - V - V - F","C":"F - F - F - V - F","D":"F - V - V - F - V","E":"V - V - V - V - F"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-284312","number":"284312","sourceNumber":"284312","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Um paciente de 25 anos de idade foi levado ao pronto-socorro após ter sido vítima de\nferimento por arma branca no sexto espaço intercostal, linha axilar anterior. Encontra-se agitado,\ndispneico ++/4+, com pulso de 125 bpm e PA de 70 x 40 mmHg. Apresenta murmúrio vesicular\ndiminuído nos ? inferiores do hemitórax direito. Abdome plano, flácido e indolor à palpação. Com\nbase nesse caso hipotético, julgue o item a seguir. A radiografia de tórax é um exame fundamental\ndurante a avaliação inicial do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-284313","number":"284313","sourceNumber":"284313","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Um paciente de 25 anos de idade foi levado ao pronto-socorro após ter sido vítima de\nferimento por arma branca no sexto espaço intercostal, linha axilar anterior. Encontra-se agitado,\ndispneico ++/4+, com pulso de 125 bpm e PA de 70 x 40 mmHg. Apresenta murmúrio vesicular\ndiminuído nos ? inferiores do hemitórax direito. Abdome plano, flácido e indolor à palpação. Com\nbase nesse caso hipotético, julgue o item a seguir. O quadro clínico do paciente associado ao local\nda lesão descarta a possibilidade de lesão abdominal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-284314","number":"284314","sourceNumber":"284314","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Um paciente de 25 anos de idade foi levado ao pronto-socorro após ter sido vítima de\nferimento por arma branca no sexto espaço intercostal, linha axilar anterior. Encontra-se agitado,\ndispneico ++/4+, com pulso de 125 bpm e PA de 70 x 40 mmHg. Apresenta murmúrio vesicular\ndiminuído nos ? inferiores do hemitórax direito. Abdome plano, flácido e indolor à palpação. Com\nbase nesse caso hipotético, julgue o item a seguir. A fístula biliopleural é uma complicação\npossível\nna evolução do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-284316","number":"284316","sourceNumber":"284316","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Um paciente de 25 anos de idade foi levado ao pronto-socorro após ter sido vítima de\nferimento por arma branca no sexto espaço intercostal, linha axilar anterior. Encontra-se agitado,\ndispneico ++/4+, com pulso de 125 bpm e PA de 70 x 40 mmHg. Apresenta murmúrio vesicular\ndiminuído nos ? inferiores do hemitórax direito. Abdome plano, flácido e indolor à palpação. Com\nbase nesse caso hipotético, julgue o item a seguir. A melhor maneira de se investigar a presença\nde lesão diafragmática no paciente é por meio da videolaparoscopia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-255671","number":"255671","sourceNumber":"255671","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Certo paciente de 38 anos de idade é levado para o hospital após sofrer dois acidentes\npor ferimento de arma de fogo, sendo um no tórax\ne outro no abdome. Chegou ao hospital em\nGlasgow 7. Ao exame físico, estava descorado, com frequência cardíaca de 135 bpm, ausculta\nabolida em hemitórax direito, local onde estava o ferimento por arma de fogo. A pressão arterial\ndele era de 70 mmHg x 50 mmHg e apresentava fáscies de dor. Além disso, apresentou fratura\nmaleolar esquerda com 3 mm de deslocamento da fratura fibular, associada à mesma. Com base\nnesse caso clínico e nos conhecimentos médicos relacionados ao ATLS, julgue o item a seguir.\n\nDeve-se solicitar imediatamente transfusão sanguínea com sangue \"O negativo\".","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-255672","number":"255672","sourceNumber":"255672","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Certo paciente de 38 anos de idade é levado para o hospital após sofrer dois acidentes\npor ferimento de arma de fogo, sendo um no tórax\ne outro no abdome. Chegou ao hospital em\nGlasgow 7. Ao exame físico, estava descorado, com frequência cardíaca de 135 bpm, ausculta\nabolida em hemitórax direito, local onde estava o ferimento por arma de fogo. A pressão arterial\ndele era de 70 mmHg x 50 mmHg e apresentava fáscies de dor. Além disso, apresentou fratura\nmaleolar esquerda com 3 mm de deslocamento da fratura fibular, associada à mesma. Com base\nnesse caso clínico e nos conhecimentos médicos relacionados ao ATLS, julgue o item a seguir.\n\nApós a intubação e a sedação, deve-se avaliar a parte neurológica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-255674","number":"255674","sourceNumber":"255674","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Certo paciente de 38 anos de idade é levado para o hospital após sofrer dois acidentes\npor ferimento de arma de fogo, sendo um no tórax\ne outro no abdome. Chegou ao hospital em\nGlasgow 7. Ao exame físico, estava descorado, com frequência cardíaca de 135 bpm, ausculta\nabolida em hemitórax direito, local onde estava o ferimento por arma de fogo. A pressão arterial\ndele era de 70 mmHg x 50 mmHg e apresentava fáscies de dor. Além disso, apresentou fratura\nmaleolar esquerda com 3 mm de deslocamento da fratura fibular, associada à mesma. Com base\nnesse caso clínico e nos conhecimentos médicos relacionados ao ATLS, julgue o item a seguir.\n\nDrenagem torácica só é indicada se houver hemotórax.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-255675","number":"255675","sourceNumber":"255675","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Certo paciente de 38 anos de idade é levado para o hospital após sofrer dois acidentes\npor ferimento de arma de fogo, sendo um no tórax\ne outro no abdome. Chegou ao hospital em\nGlasgow 7. Ao exame físico, estava descorado, com frequência cardíaca de 135 bpm, ausculta\nabolida em hemitórax direito, local onde estava o ferimento por arma de fogo. A pressão arterial\ndele era de 70 mmHg x 50 mmHg e apresentava fáscies de dor. Além disso, apresentou fratura\nmaleolar esquerda com 3 mm de deslocamento da fratura fibular, associada à mesma. Com base\nnesse caso clínico e nos conhecimentos médicos relacionados ao ATLS, julgue o item a seguir.\n\nTraumas por arma de fogo podem conter projéteis, e sua retirada pode ocasionar piora\nhemodinâmica, dependendo do local.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-239270","number":"239270","sourceNumber":"239270","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Um paciente de 32 anos de idade é levado à sala de trauma pelo Corpo de Bombeiros\n25 minutos após ser vítima de acidente de moto\nversus anteparo. Testemunhas disseram que o\npaciente foi arremessado a uma distância de cerca de 10 metros, e que ele usava capacete. Na\ncena, estava eupneico e mantinha nível de consciência normal. Durante o transporte, começou a\nqueixar-se de \"falta de ar\". A avaliação inicial do plantonista da sala de trauma foi a seguinte: A\n-\nvias aéreas pérvias, com colar cervical; B - taquidispneico, FR = 54 irpm, murmúrios audíveis e\nsimétricos em ambos hemitóraxes, SpO2 = 93%; C - FC = 130 bpm, PA = 89 mmHg x 68 mmHg,\nbulhas cardíacas abafadas, escoriações no abdome e nos membros, sem sangramento ativo.\n\nToque retal sem alterações; D - Abertura ocular ao chamado, fala confusa, localizava dor. Pupilas\nisocóricas e fotorreagentes; E - Membro inferior esquerdo encurtado e em rotação lateral, com dor à\nmanipulação. Coluna sem dor à palpação. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. As alterações do membro inferior descritas sugerem\nfratura de tíbia que deve ser imobilizada até que se possa realizar a fixação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-196683","number":"196683","sourceNumber":"196683","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Paciente de 6 meses e 20 dias de vida, nascido com 35 semanas de idade gestacional,\né levado a uma consulta de puericultura pela\nmãe. Recebe aleitamento materno, papas de frutas e\nduas papas principais. A mãe demonstra muita preocupação, pois o lactente não senta sem apoio e\nnão rola no leito. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. Uma vez que o bebê ainda não rola no leito, não é necessário que durma em berço\ncom grades apropriadas, podendo ser estimulado o coleito.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-177657","number":"177657","sourceNumber":"177657","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"I.F.S., menino de 3 anos de idade em acompanhamento em serviço de referência por\ndiagnóstico de nefroblastoma, aguardando tratamento cirúrgico, é levado ao pronto atendimento,\npor sua mãe, devido a queixas de diarreia há um dia, com cinco episódios de evacuação líquidas\nsem produtos patológicos, diminuição da ingestão alimentar e discreta diminuição do volume\nurinário. Não refere vômitos ou febre. As mucosas estão úmidas e coradas. A criança está alerta\nbrincando pelo consultório. O exame abdominal revela discreto desconforto difuso, sem\nperitonismo, além da massa abdominal palpável. Aproveitando a oportunidade da consulta médica,\na mãe do paciente resolve tirar algumas dúvidas sobre o transporte dele no carro. Com base nas\ninformações apresentadas no caso clínico e conhecimentos correlatos, julgue o item a seguir.\n\nCrianças entre 1 e 4 anos de idade devem ser transportadas no carro, para prevenção de traumas,\ncom dispositivos denominados \"cadeirinhas\".","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-177664","number":"177664","sourceNumber":"177664","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"I.F.S., menino de 3 anos de idade em acompanhamento em serviço de referência por\ndiagnóstico de nefroblastoma, aguardando tratamento cirúrgico, é levado ao pronto atendimento,\npor sua mãe, devido a queixas de diarreia há um dia, com cinco episódios de evacuação líquidas\nsem produtos patológicos, diminuição da ingestão alimentar e discreta diminuição do volume\nurinário. Não refere vômitos ou febre. As mucosas estão úmidas e coradas. A criança está alerta\nbrincando pelo consultório. O exame abdominal revela discreto desconforto difuso, sem\nperitonismo, além da massa abdominal palpável. Aproveitando a oportunidade da consulta médica,\na mãe do paciente resolve tirar algumas dúvidas sobre o transporte dele no carro. Com base nas\ninformações apresentadas no caso clínico e conhecimentos correlatos, julgue o item a seguir. A\ncadeirinha deve ser necessariamente posicionada no sentido oposto ao do restante dos bancos dos\ncarros.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-177609","number":"177609","sourceNumber":"177609","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"C.A.S., filho de J.A.S., agora está com 9 meses de idade. A mãe, muito atarefada\ndevido às responsabilidades maternais\nassociadas à necessidade de prover o sustento da família,\nresolveu comprar um andador (aparelho com rodas no qual a criança fica suspensa, podendo se\npropulsionar para frente ou para os lados), para que o filho tivesse mais liberdade para\n\nlocomover-se pela casa antes de aprender a andar. A respeito do andador e da relação desse\nobjeto com os traumas infantis, julgue o item a seguir. O andador pode ser considerado um\ninstrumento para prevenção de traumas infantis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-152088","number":"152088","sourceNumber":"152088","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Considere, hipoteticamente, a ocorrência de um acidente do tipo explosão após um raio\natingir certo tanque de combustível em uma usina onde vários funcionários estavam trabalhando.\n\nUma vítima foi levada ao pronto-socorro pelos bombeiros com imobilização cervical e em prancha\nrígida, e, segundo o socorrista,\napresentava grande lesão penetrante em hemitórax direito, PA de\n90 mmHg x 60 mmHg, abertura ocular somente quando solicitado, pronunciando palavras\ndesconexas, e com flexão anormal a estímulos dolorosos. Evoluiu com FAST negativo e\nestabilidade hemodinâmica. A respeito do caso clínico apresentado, julgue o item a seguir.\n\nPacientes como o citado, transportados em pranchas longas, devem ser mantidos nelas por\nperíodos indeterminados, mesmo em ambiente\nhospitalar, como forma de proteção da coluna até o\ndescarte de lesões inferiores à região cervical.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-152094","number":"152094","sourceNumber":"152094","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Considere hipoteticamente a ocorrência de um acidente do tipo explosão após um raio\natingir certo tanque de combustível em uma usina onde vários funcionários estavam trabalhando.\nUma vítima foi levada ao pronto-socorro pelos bombeiros com imobilização cervical e em prancha\nrígida, e, segundo o socorrista, apresentava grande lesão penetrante em hemitórax direito, PA de\n90 mmHg x 60 mmHg, abertura ocular somente quando solicitado, pronunciando palavras\ndesconexas, e com flexão anormal a estímulos dolorosos. Evoluiu com FAST negativo e\nestabilidade hemodinâmica. A respeito do caso clínico apresentado, julgue o item a seguir. Nos\ncasos de ferimentos torácicos penetrantes em que a lesão apresenta diâmetro maior ou igual a dois\nterços do diâmetro da traqueia, o ar tende a passar preferencialmente pela lesão da parede\ntorácica, o que exige a realização de curativo fixado em três dos respectivos lados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-152100","number":"152100","sourceNumber":"152100","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Considere hipoteticamente a ocorrência de um acidente do tipo explosão após um raio\natingir certo tanque de combustível em uma usina onde vários funcionários estavam trabalhando.\nUma vítima foi levada ao pronto-socorro pelos bombeiros com imobilização cervical e em prancha\nrígida, e, segundo o socorrista, apresentava grande lesão penetrante em hemitórax direito, PA de\n90 mmHg x 60 mmHg, abertura ocular somente quando solicitado, pronunciando palavras\ndesconexas, e com flexão anormal a estímulos dolorosos. Evoluiu com FAST negativo e\nestabilidade hemodinâmica. A respeito do caso clínico apresentado, julgue o item a seguir. No uso\nde métodos diagnósticos no trauma abdominal, os pacientes estáveis necessitam de exames\nadicionais após a realização de uma ultrassonografia negativa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-152113","number":"152113","sourceNumber":"152113","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Considere as três situações seguintes: Paciente 1 - O. S., 34 anos de idade, queixa-se\nde dispneia e desconforto respiratório leve, FR\n= 19 irpm, Sat O2 = 98% e PA de 130 x 80 mmHg;\nPaciente 2 - B. M. S., 65 anos de idade, trabalhador rural, vai à consulta para esclarecer dúvidas a\nrespeito de uma mancha escura na face, perda ponderal e massa palpável no abdome; Paciente 3 -\nAdolescente deu entrada na emergência, após acidente motociclístico, com sangramento ativo de\ndifícil controle em MSE, FC = 99 bpm, PA de 110 x 70 mmHg, consciente e manifestando sede.\n\nCom relação aos casos clínicos apresentados, julgue o item a seguir. O diagnóstico do Paciente 1\npoderia ser pneumotórax primário de pequena monta (<20%) que, quando constatado em imagem\nde tomografia, deve ser tratado com toracostomia com drenagem pleural fechada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-291460","number":"291460","sourceNumber":"291460","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Um recém-nascido com 20 dias de vida dá entrada em serviço médico de urgência com\nhistória referida de queda da cama após ter rolado para fora dela há 6 horas. Pais referem\nhipoatividade desde então. Ao exame, está em regular estado geral e apresenta hematoma\nsubgaleal em região parietal. A fundoscopia evidencia hemorragia retiniana bilateral e a tomografia\nde crânio apresenta hemorragia subaracnóidea, sem sinais de fratura. Com base nos dados\napresentados, o diagnóstico mais provável é:","options":{"A":"Traumatismo crânio encefálico decorrente da queda da cama.","B":"Acidente vascular cerebral decorrente de malformação vascular.","C":"Síndrome de shaken baby (bebê sacudido) decorrente de maus-tratos.","D":"Tromboembolismo gorduroso resultante da queda."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-273333","number":"273333","sourceNumber":"273333","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Na abordagem de um paciente com traumatismo cranioencefálico, de acordo com os\ncritérios de avaliação pela escala de Glasgow, a ocorrência de abertura ocular espontânea,\nresposta verbal apresentando confusão e obediência a comando como resposta motora indicam\ntrauma:","options":{"A":"Leve.","B":"Moderado.","C":"Grave.","D":"Permanente e irreversível."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-273335","number":"273335","sourceNumber":"273335","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Com relação ao tratamento de pacientes vítimas de trauma, a alternativa correta é:","options":{"A":"O uso de Fator VII recombinante não foi associado redução de necessidade de hemoderivados\nem vítimas de trauma fechado que necessitam de\npolitransfusão.","B":"As primeiras medidas são infusão de fluido e hemoderivados, sendo o controle da hemorragia\nrealizado posteriormente, depois de atingidos os objetivos da ressuscitação.","C":"O uso de etomidato não está associado à insuficiência suprarrenal, quando utilizado em dose\núnica para intubação.","D":"A infusão de grande quantidade de fluidos pode ocasionar a Síndrome Compartimental\nAbdominal, mesmo nos pacientes que não apresentam lesões\nintra-abdominais traumáticas."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-227369","number":"227369","sourceNumber":"227369","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Paciente de vinte e cinco anos de idade, vítima de acidente automobilístico com\ncapotamento ocorrido havia 8 horas, foi levado\nao pronto-socorro, onde deu entrada consciente,\norientado, imobilizado em prancha rígida, com colar cervical. O paciente apresentava sinais vitais\nnormais, quadro de dor em região cervical, abdominal e lacerações em membros superiores e\ninferiores. Com relação a esse caso clínico e aos múltiplos aspectos a ele relacionados, julgue o\nitem a seguir. Como os sinais vitais do referido paciente estão normais, deve-se descartar a\npossibilidade de hemorragia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-227371","number":"227371","sourceNumber":"227371","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Paciente de vinte e cinco anos de idade, vítima de acidente automobilístico com\ncapotamento ocorrido havia 8 horas, foi levado\nao pronto-socorro, onde deu entrada consciente,\norientado, imobilizado em prancha rígida, com colar cervical. O paciente apresentava sinais vitais\nnormais, quadro de dor em região cervical, abdominal e lacerações em membros superiores e\ninferiores. Com relação a esse caso clínico e aos múltiplos aspectos a ele relacionados, julgue o\nitem a seguir. O colar cervical deverá ser retirado somente na hipótese de, após a realização de\nexame radiológico da coluna cervical, este não evidenciar fraturas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-212061","number":"212061","sourceNumber":"212061","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"A respeito de pacientes acometidos por traumas graves, julgue o próximo item. Um\npaciente com suspeita de trauma craniano e\nescore 15 de Glasgow deve ser submetido à intubação\norotraqueal imediatamente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-212058","number":"212058","sourceNumber":"212058","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"A respeito de pacientes acometidos por traumas graves, julgue o próximo item. O\ntratamento de urgência para um paciente com\npneumotórax hipertensivo é a intubação orotraqueal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-206132","number":"206132","sourceNumber":"206132","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"O nível neurológico da lesão medular é definido pelo segmento mais caudal da medula,\nque se traduz através de funções motoras e\nsensoriais normais em ambos os lados do corpo. A\npresença da sensibilidade no xifoide corresponde a qual segmento do nervo espinhal?","options":{"A":"C6","B":"C7","C":"T4","D":"T8"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-183901","number":"183901","sourceNumber":"183901","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Com relação aos pacientes politraumatizados, julgue o item a seguir. Na fase inicial\nrefratária, o choque hemorrágico gera, tipicamente, acidose mista na gasometria - metabólica e\nrespiratória.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-351585","number":"351585","sourceNumber":"351585","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Ao se deparar com possível situação de maus-tratos a criança ou adolescente, é\nCORRETO afirmar que o médico deve:","options":{"A":"Conduzir minucioso processo de investigação antes de oferecer denúncia, uma vez que pode\nser legalmente penalizado por denunciação\ncaluniosa.","B":"Emitir ficha de notificação individual, garantir a continuidade do tratamento médico e acionar\nimediatamente conselho tutelar em casos em que haja risco emergencial à segurança do paciente.","C":"Registrar o caso detalhadamente em prontuário, emitindo ficha de notificação, apenas se há\nconfirmação da violência, solicitando também a confecção de boletim de ocorrência.","D":"Acionar imediatamente serviço policial independente do caso, ocupando-se somente da\navaliação clínica e garantia de continuidade do tratamento ambulatorial."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-321176","number":"321176","sourceNumber":"321176","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"O maior número de eventos traumáticos com crianças pequenas, até o fim da idade\nescolar, acontece no seu próprio domicílio. A\nprevenção de lesões que ocorrem no lar, segundo os\nespecialistas, apoia-se na orientação e na conscientização dos pais para que promovam mudanças\nno seu comportamento, no sentido de uma supervisão mais efetiva e da eliminação dos riscos\ndentro de casa. Nesse sentido, é CORRETO afirmar que:","options":{"A":"Manter os produtos em sua embalagem original e nunca reutilizar frascos são formas de prevenir\nintoxicações.","B":"Ligar mais de um aparelho em uma mesma tomada, evitando assim que estes fiquem\nespalhados pela casa, é uma forma de prevenir choques elétricos.","C":"Se o bebê tem um cercado, é necessário que a malha seja bem apertada, com buracos maiores\nque 2cm e menores que 5cm.","D":"Uso de andadores é uma forma de prevenir quedas."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-321179","number":"321179","sourceNumber":"321179","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Sobre o suporte às vítimas de violência doméstica na pediatria, é CORRETO afirmar\nque:","options":{"A":"A síndrome de Munchausen por procuração é uma doença de difícil controle, definida como\nforma de violência na qual a criança ou o\nadolescente são levados para cuidados médicos de forma\ninsistente e em frequência acima do esperado.","B":"A notificação do diagnóstico ou suspeita de violência não é compulsória, e deve ser feita ou não\nsegundo decisão da vítima juntamente ao médico\nresponsável.","C":"Os pais e a família sempre são os melhores a cuidar de sua prole e, na consulta pediátrica, eles\nsempre falam a verdade e procurando o melhor para seus filhos.","D":"Todo ato sexual com adolescente ou criança menor de 16 anos é considerado crime de estupro\npelo Código Penal Brasileiro."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-321182","number":"321182","sourceNumber":"321182","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Você atende um paciente politraumatizado, queda de motocicleta, trazido pelo SAMU.\nPaciente se encontra hipotenso, emite sons ao estímulo doloroso, abre olhos ao comando verbal,\nresposta motora localizando dor. Na sala de emergência a equipe toma as condutas iniciais de\ntratamento. Baseado nesta abordagem, analise as afirmativas a seguir: I- A ultrassonografia não é\nimportante para este caso na sala de trauma. II- Se no exame do tórax murmúrio vesicular abolido e\nmacicez na percussão, a principal hipótese é de hemotórax. III- Indicado intubação orotraqueal,\npois Glasgow é menor que 9. IV- A avaliação se inicia pela inspeção de vias aéreas, de sua\nperviedade e da capacidade de oxigenação. Estão CORRETAS as afirmativas:","options":{"A":"I e II apenas.","B":"II e III apenas.","C":"II e IV apenas.","D":"III e IV apenas."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-08-321184","number":"321184","sourceNumber":"321184","collectionBlock":"med:med-cirurgia-med-cir-08","collectionLabel":"MED · MED CIR 08","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 08","subtopic":"","stem":"Paciente de 23 anos envolveu-se em uma briga de torcidas e foi agredido por arma\nbranca. Chega ao Pronto-Socorro após 40\nminutos do ocorrido, onde você está de plantão, e no\nexame físico apresenta-se: corado, eupneico, afebril, agitado e boa perfusão capilar. MVF bilateral\ncom lesão corto contusa perfurante no 6° espaço intercostal esquerdo, linha hemiaxilar, BNRNF,\nFC: 80bpm, pulsos amplos. Abdome livre e plano. Considerando o caso apresentado, é CORRETO\nafirmar que a conduta seria de:","options":{"A":"Solicitar um FAST estendido para avaliar derrame pericárdico.","B":"Solicitar tomografia de abdome.","C":"Realizar lavagem peritoneal diagnóstica.","D":"Realizar laparoscopia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 08/MED CIR 08.txt","sourceLabel":"MED · MED CIR 08","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 08","MED"],"answerSource":"missing","commentDeferred":true}]};
